INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_', 2, '{"en": "\u2022", "zh-CN": "\u203b"}', '{}', '{}', '{"part_of_speech":"Noun"}');
INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_bakumatsu', 2, '{"en": "Bakumatsu", "zh-CN": "\u5e55\u672b"}', '{}', '{}', '{"part_of_speech":"Noun","remarks":"指日本江户时代末期，大约从1853年美国海军准将马修·佩里的黑船来航，到1867年德川幕府末代将军德川庆喜大政奉还期间的历史时期。这段时期标志着日本从封建制度向现代化国家的过渡，伴随着内外部的巨大变革和动荡。"}');
INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_obschina', 2, '{"en": "Obschina", "zh-CN": "\u6751\u793e"}', '{}', '{}', '{"part_of_speech":"Noun","remarks":"是俄国的传统农村自治单位，起源可以追溯到中世纪。这种制度是由村民共同拥有和管理土地的形式，村民们共同负责土地的分配、税收和社会事务的管理。Obschina在19世纪俄国社会中起到了重要作用，尤其是在农奴制时代，村社还承担了许多行政和社会功能。 在农业改革中，特别是1861年农奴"}');
INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_political_rigidity', 2, '{"en": "Political Rigidity", "zh-CN": "\u653f\u6cbb\u7a33\u5b9a\u5ea6"}', '{}', '{}', '{"part_of_speech":"Noun"}');
INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_the_gag_rule', 2, '{"en": "The Gag Rule", "zh-CN": "\u5c01\u53e3\u4ee4"}', '{}', '{"en": ["Gag Rule"]}', '{"part_of_speech":"Noun","remarks":"在美国历史上，“Gag Rule” 特指1836年至1844年间美国国会通过的一系列决议，这些决议禁止讨论和审议有关废奴请愿的所有议题。这些封口令是由支持奴隶制的议员推动的，目的是阻止反奴隶制的请愿在国会中被讨论。最终，这些规则在1844年被废除。"}');
INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('victoria3_zemstvo', 2, '{"en": "Zemstvo", "zh-CN": "\u5730\u65b9\u81ea\u6cbb\u673a\u6784"}', '{}', '{"en": ["Zemstvos"]}', '{"part_of_speech":"Noun","remarks":"是19世纪俄国进行地方行政改革时创建的一种地方政府机构。它们负责地方的管理、公共事务和地方税收。 Zemstvos通常由地方选举产生的代表组成，负责处理地方教育、公共卫生、交通和其他地方性事务。这些机构是在1864年的俄国改革中设立的，目的是分担中央政府的管理负担，并增强地方自治"}');
