INSERT INTO entries (entry_id, glossary_id, translations, abbreviations, variants, raw_metadata) VALUES ('stellaris_hawking_radiation', 4, '{"en": "Hawking Radiation", "zh-CN": "\u970d\u91d1\u8f90\u5c04"}', '{}', '{}', '{"part_of_speech":"Noun","remarks":"霍金辐射（英语：Hawking radiation）是以量子效应理论推测出的一种由黑洞散发出来的热辐射。此理论在1974年由物理学家史蒂芬·霍金提出。有了霍金辐射的理论就能说明如何降低黑洞的质量而导致黑洞蒸散的现象。"}');
